import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {repositoryLicensePolicyRoute} from '../routes/license-policy-route'
import {saveRepositoryPolicy} from '../services/policy'
import type {SaveRepositoryPolicyPayload} from '../types/save-policy'
import type {PackagePolicy} from '../types/packages'

export function useSaveRepositoryPolicyMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(repositoryLicensePolicyRoute, 'mainQuery')

  const {organization, repository} = useRouteParams(repositoryLicensePolicyRoute)
  if (!organization) {
    throw new Error('Organization slug not found in route parameters')
  }
  if (!repository) {
    throw new Error('Repository slug not found in route parameters')
  }

  return useMutation({
    mutationFn: async ({
      context,
      deleteSpdxIds,
      deletePackages,
    }: {
      context: string
      deleteSpdxIds: string[]
      deletePackages: PackagePolicy[]
    }) => {
      // Short-circuit when there is nothing to save: the backend returns a 500 for empty payloads.
      // We still want the success-path UX (invalidate + scroll + info banner) to fire, so we resolve
      // with an empty response and let onSuccess/onSettled run as usual.
      if (deleteSpdxIds.length === 0 && deletePackages.length === 0) {
        return {}
      }

      const payload: SaveRepositoryPolicyPayload = {
        repository_slug: repository,
        organization_slug: organization,
        context,
        delete_spdx_ids: deleteSpdxIds,
        delete_packages: deletePackages,
      }

      // Call service which interacts with the OLC API
      return await saveRepositoryPolicy(payload)
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({queryKey})
    },
    onError: () => {},
    onSettled: () => {
      window.scrollTo({top: 0})
    },
  })
}
