import {Stack} from '@primer/react'

import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {useCallback, useMemo} from 'react'

import {LicensePolicyPage} from '../LicensePolicyPage/LicensePolicyPage'
import {LicensePolicyBackLink} from '../LicensePolicyPage/LicensePolicyBackLink'

import {useAddAllowedLicensesToEnterpriseMutation} from '../../hooks/use-add-allowed-licenses-mutation'
import {useDeleteAllowedLicensesFromEnterpriseMutation} from '../../hooks/use-delete-allowed-licenses-mutation'
import {useDeletePackageExceptionsFromEnterpriseMutation} from '../../hooks/use-delete-package-exceptions-mutation'
import {usePolicyLicensesDraftState} from '../../hooks/use-policy-licenses-draft-state'
import {createStagedPackageException, usePolicyPackagesDraftState} from '../../hooks/use-policy-packages-draft-state'
import {useSaveEnterprisePolicyMutation} from '../../hooks/use-save-enterprise-policy-mutation'
import {useValidateLicensesMutation} from '../../hooks/use-validate-licenses-mutation'
import {enterpriseLicensePolicyRoute, enterpriseSingleLicensePolicyRoute} from '../../routes/license-policy-route'
import type {EnterpriseSingleLicensePolicyResponse} from '../../types/policies'
import {toGenericLicensePolicyResponse} from '../../types/policies'
import {PolicyLevel} from '../../types/policy-levels'
import {PolicyEditMode, usePolicyEditMode} from '../../context/PolicyEditModeContext'
import {useUserPermissions} from '../../context/UserPermissionsContext'
import type {
  AddAllowedLicensesMutation,
  DeleteAllowedLicensesMutation,
  AddPackageExceptionsMutation,
  DeletePackageExceptionsMutation,
} from '../../types/mutations'
import {extractFailedSpdxIds} from '../../types/save-policy'

export function EnterpriseLicensePolicyPage({
  preview,
  data,
}: {
  preview: boolean
  data: EnterpriseSingleLicensePolicyResponse
}) {
  const addAllowedLicensesMutation = useAddAllowedLicensesToEnterpriseMutation()
  const deleteAllowedLicensesMutation = useDeleteAllowedLicensesFromEnterpriseMutation()
  const deletePackageExceptionsMutation = useDeletePackageExceptionsFromEnterpriseMutation()
  const validateLicensesMutation = useValidateLicensesMutation()

  const {business} = useRouteParams(enterpriseSingleLicensePolicyRoute)
  const {canManagePolicy} = useUserPermissions()

  const overviewHref = enterpriseLicensePolicyRoute.generatePath({business})
  const showBackLink = !!data.enterprise_overview_enabled

  const editMode = usePolicyEditMode()
  const isDraftMode = editMode === PolicyEditMode.Draft

  const {allLicenses, addSpdxIds, deleteSpdxIds, stageAddLicenses, stageDeleteLicenses, resetLicensesFromUpstream} =
    usePolicyLicensesDraftState(PolicyLevel.Enterprise, data.allowed)

  const {allPackages, addPackages, deletePackages, stageAddPackages, stageDeletePackages, resetPackagesFromUpstream} =
    usePolicyPackagesDraftState(PolicyLevel.Enterprise, data.packages)

  const resetAllFromUpstream = useCallback(() => {
    resetLicensesFromUpstream()
    resetPackagesFromUpstream()
  }, [resetLicensesFromUpstream, resetPackagesFromUpstream])

  const saveEnterprisePolicyMutation = useSaveEnterprisePolicyMutation({resetFromUpstream: resetAllFromUpstream})

  const saveFailedSpdxIds = useMemo(
    () => extractFailedSpdxIds(saveEnterprisePolicyMutation.data),
    [saveEnterprisePolicyMutation.data],
  )

  const onSaveDraftPolicy = () => {
    saveEnterprisePolicyMutation.mutate({
      context: 'distributed',
      addSpdxIds,
      deleteSpdxIds,
      addPackages,
      deletePackages,
    })
  }

  const addAllowedLicensesMutationToUse: AddAllowedLicensesMutation = useMemo(() => {
    if (!isDraftMode) return addAllowedLicensesMutation

    return {
      ...validateLicensesMutation,
      mutate: ({spdxIds, onClose}) => {
        validateLicensesMutation.mutate(spdxIds, {
          onSuccess: result => {
            if (result.valid_spdx_ids.length > 0) {
              stageAddLicenses(result.valid_spdx_ids)
            }
            onClose?.()
          },
        })
      },
      data: {failed_spdx_ids: validateLicensesMutation.data?.invalid_spdx_ids},
    }
  }, [addAllowedLicensesMutation, isDraftMode, stageAddLicenses, validateLicensesMutation])

  const deleteAllowedLicensesMutationToUse: DeleteAllowedLicensesMutation = useMemo(() => {
    if (!isDraftMode) return deleteAllowedLicensesMutation

    return {
      mutate: ({spdxIds}) => {
        stageDeleteLicenses(spdxIds)
      },
      isError: false,
      isPending: false,
      reset: () => {},
    }
  }, [deleteAllowedLicensesMutation, isDraftMode, stageDeleteLicenses])

  const deletePackageExceptionsMutationToUse: DeletePackageExceptionsMutation = useMemo(() => {
    if (!isDraftMode) return deletePackageExceptionsMutation

    return {
      mutate: ({packages}) => {
        stageDeletePackages(packages)
      },
      isError: false,
      isPending: false,
      reset: () => {},
    }
  }, [deletePackageExceptionsMutation, isDraftMode, stageDeletePackages])

  const addPackageExceptionsMutationToUse: AddPackageExceptionsMutation | undefined = useMemo(() => {
    if (!isDraftMode) return undefined

    return {
      mutate: ({packages, onClose}) => {
        const staged = packages.map(p =>
          createStagedPackageException({
            name: p.name,
            packageManager: p.package_manager,
            level: PolicyLevel.Enterprise,
          }),
        )
        stageAddPackages(staged)
        onClose?.()
      },
      isError: false,
      isPending: false,
      reset: () => {},
    }
  }, [isDraftMode, stageAddPackages])

  const policyData = useMemo(
    () => ({
      ...toGenericLicensePolicyResponse(PolicyLevel.Enterprise, data),
      allowed: isDraftMode ? allLicenses : data.allowed,
      packages: isDraftMode ? allPackages : data.packages,
    }),
    [data, isDraftMode, allLicenses, allPackages],
  )

  const draftSaveRevertControls =
    isDraftMode && canManagePolicy
      ? {
          addCount: addSpdxIds.length + addPackages.length,
          deleteCount: deleteSpdxIds.length + deletePackages.length,
          onSave: onSaveDraftPolicy,
          onRevert: resetAllFromUpstream,
          resetOnRevert: () => {
            saveEnterprisePolicyMutation.reset()
            validateLicensesMutation.reset()
          },
          saveMutation: saveEnterprisePolicyMutation,
        }
      : undefined

  return (
    <Stack gap="tight">
      {showBackLink && <LicensePolicyBackLink href={overviewHref} label="License compliance" />}
      <LicensePolicyPage
        title={canManagePolicy ? 'Edit license policy' : 'License policy'}
        policyName={canManagePolicy ? 'Default policy' : undefined}
        preview={preview}
        data={policyData}
        pickerEnabled={!!data.enterprise_overview_enabled}
        pageDescription='This license policy will apply to repositories targeted by a branch protection ruleset with the "Require license compliance results before merging" rule.'
        licensesDescription="Dependencies with these licenses can be used in all repositories in your enterprise without review."
        exceptionsDescription="These packages can be used in all repositories in your enterprise without review."
        addAllowedLicensesMutation={addAllowedLicensesMutationToUse}
        deleteAllowedLicensesMutation={deleteAllowedLicensesMutationToUse}
        addPackageExceptionsMutation={isDraftMode && canManagePolicy ? addPackageExceptionsMutationToUse : undefined}
        deletePackageExceptionsMutation={deletePackageExceptionsMutationToUse}
        failedSpdxIds={saveFailedSpdxIds}
        onDismissFailedSpdxIds={() => saveEnterprisePolicyMutation.reset()}
        draftSaveRevert={draftSaveRevertControls}
      />
    </Stack>
  )
}
