import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {enterpriseSingleLicensePolicyRoute} from '../routes/license-policy-route'
import {saveEnterprisePolicy} from '../services/policy'
import type {SaveEnterprisePolicyPayload} from '../types/save-policy'
import {extractFailedSpdxIds} from '../types/save-policy'
import type {PackagePolicy} from '../types/packages'
import type {EnterpriseSingleLicensePolicyResponse} from '../types/policies'

export function useSaveEnterprisePolicyMutation({resetFromUpstream}: {resetFromUpstream: () => void}) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(enterpriseSingleLicensePolicyRoute, 'mainQuery')

  const {business} = useRouteParams(enterpriseSingleLicensePolicyRoute)
  if (!business) {
    throw new Error('Business slug not found in route parameters')
  }

  return useMutation({
    mutationFn: async ({
      context,
      addSpdxIds,
      deleteSpdxIds,
      addPackages,
      deletePackages,
    }: {
      context: string
      addSpdxIds: string[]
      deleteSpdxIds: string[]
      addPackages: PackagePolicy[]
      deletePackages: PackagePolicy[]
    }) => {
      // Short-circuit when there is nothing to save: the backend returns a 500 for empty payloads.
      // We still want the success-path UX (invalidate + scroll + info banner) to fire, so we resolve
      // with an empty response and let onSuccess/onSettled run as usual.
      if (
        addSpdxIds.length === 0 &&
        deleteSpdxIds.length === 0 &&
        addPackages.length === 0 &&
        deletePackages.length === 0
      ) {
        return {}
      }

      const payload: SaveEnterprisePolicyPayload = {
        enterprise_slug: business,
        context,
        add_spdx_ids: addSpdxIds,
        delete_spdx_ids: deleteSpdxIds,
        add_packages: addPackages,
        delete_packages: deletePackages,
      }

      // Call service which interacts with the OLC API
      return await saveEnterprisePolicy(payload)
    },
    onSuccess: async data => {
      const hasFailures = extractFailedSpdxIds(data).length > 0

      const getUpstreamAllowedKey = () => {
        const cached = queryClient.getQueryData<EnterpriseSingleLicensePolicyResponse>(queryKey)
        return (cached?.allowed ?? []).map(l => l.spdx_id).join('\u0000')
      }

      const beforeAllowedKey = getUpstreamAllowedKey()

      // Always refresh the license policy data after a successful save.
      // This is important even when the server returns a 2xx response with `failed_spdx_ids`,
      // since the server may have applied a subset of changes.
      try {
        await queryClient.invalidateQueries({queryKey})
      } finally {
        if (hasFailures) {
          const afterAllowedKey = getUpstreamAllowedKey()

          // If the upstream query did not meaningfully change (e.g. all submitted licenses were invalid),
          // force-reset the draft state so the UI reflects the query's source of truth.
          if (beforeAllowedKey === afterAllowedKey) {
            resetFromUpstream()
          }
        }
      }
    },
    onError: () => {
      // No special error handling needed here since the service throws an error which is surfaced by useMutation's error state.
      // The main page will show an error banner when the mutation fails, and we want to ensure that happens even if the server returns a 2xx with `failed_spdx_ids`.
    },
    onSettled: () => {
      window.scrollTo({top: 0})
    },
  })
}
