import {useState} from 'react'
import {licensesById} from '../../license-categories'
import {BaseListItem} from '../BaseListView/BaseListItem'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {ShieldLockIcon} from '@primer/octicons-react'
import {IconButton, Link, AnchoredOverlay} from '@primer/react'
import {useEnterpriseInfo} from '../../context/EnterpriseInfoContext'
import {PolicyLevel} from '../../types/policy-levels'
import {usePolicyLevel} from '../../context/PolicyLevelContext'

interface AllowedLicensesListItemProps {
  spdxID: string
  spdxName: string
  dateAdded: string
  level: PolicyLevel
  isSelected: boolean
  hasCheckboxes: boolean
  onSelect: () => void
  onDelete?: (spdxID: string) => void
}

export function AllowedLicensesListItem({
  spdxID,
  spdxName,
  dateAdded,
  level,
  isSelected,
  hasCheckboxes,
  onSelect,
  onDelete,
}: AllowedLicensesListItemProps) {
  const [open, setOpen] = useState(false)
  const {enterpriseName, enterpriseSlug} = useEnterpriseInfo()
  const pageLevel = usePolicyLevel()

  const description = `Added ${dateAdded} • ${spdxName}`
  const category = licensesById[spdxID]?.category
  const label = category ? <ListItemTrailingBadge key={category} title={category} variant="secondary" /> : undefined

  const renderEnterpriseShield = () => {
    // Repository level policy page renders shield icon for enterprise-inherited licenses.
    if (pageLevel !== PolicyLevel.Repository || level !== PolicyLevel.Enterprise || !enterpriseName || !enterpriseSlug)
      return null
    return (
      <AnchoredOverlay
        open={open}
        onOpen={() => setOpen(true)}
        onClose={() => setOpen(false)}
        side="outside-top"
        width="small"
        renderAnchor={props => (
          <IconButton
            {...props}
            icon={ShieldLockIcon}
            aria-label={`Managed by ${enterpriseName}`}
            variant="invisible"
          />
        )}
      >
        <p className="tmp-p-3 m-0">
          This allowed license is managed by{' '}
          <Link inline href={`/enterprises/${enterpriseSlug}`}>
            {enterpriseName}
          </Link>
          .
        </p>
      </AnchoredOverlay>
    )
  }

  return (
    <BaseListItem
      title={spdxID}
      description={description}
      isSelected={isSelected}
      isWildcard={false}
      label={label}
      trailingContent={renderEnterpriseShield()}
      onSelect={onSelect}
      onDelete={onDelete ? () => onDelete(spdxID) : undefined}
      hasCheckboxes={hasCheckboxes}
    />
  )
}
