import type {LicenseEntry} from '../../types/licenses'
import {AllowedLicensesHeader} from '../AllowedLicenses/AllowedLicensesHeader'
import {AllowedLicensesList} from '../AllowedLicenses/AllowedLicensesList'
import type {MenuItemConfig} from '../BaseListView/BaseListHeader'
import type {AddAllowedLicensesMutation, DeleteAllowedLicensesMutation} from '../../types/mutations'
import {LicensePolicyBanner} from './LicensePolicyBanner'
import pluralize from 'pluralize'

const EMPTY_SPDX_IDS: string[] = []

interface LicensePolicyAllowedLicensesProps {
  description?: string
  licenses: LicenseEntry[]
  datePolicyAdded: string
  menuItems?: MenuItemConfig[]
  addAllowedLicensesMutation?: AddAllowedLicensesMutation
  deleteAllowedLicensesMutation?: DeleteAllowedLicensesMutation
  failedSpdxIds?: string[]
  dismissFailedLicensesBanner?: () => void
}

export function LicensePolicyAllowedLicenses({
  description,
  licenses,
  datePolicyAdded,
  menuItems,
  addAllowedLicensesMutation,
  deleteAllowedLicensesMutation,
  failedSpdxIds: failedSpdxIdsFromSave,
  dismissFailedLicensesBanner,
  ...sectionProps
}: LicensePolicyAllowedLicensesProps & React.HTMLAttributes<HTMLElement>) {
  const failedSpdxIdsFromAdd = addAllowedLicensesMutation?.data?.failed_spdx_ids ?? []
  const saveFailedSpdxIds = failedSpdxIdsFromSave ?? EMPTY_SPDX_IDS
  const hasSaveFailures = saveFailedSpdxIds.length > 0
  const failedSpdxIds = hasSaveFailures ? saveFailedSpdxIds : failedSpdxIdsFromAdd
  const failedSpdxIdsDescription = hasSaveFailures
    ? `${pluralize('license', failedSpdxIds.length, true)} failed to be added when saving.`
    : `${pluralize('license', failedSpdxIds.length, true)} failed to be added through manual input.`

  return (
    <section {...sectionProps}>
      <AllowedLicensesHeader description={description || ''} menuItems={menuItems} />

      {addAllowedLicensesMutation?.isError && failedSpdxIdsFromAdd.length === 0 && (
        <LicensePolicyBanner
          variant="critical"
          title="Unable to add licenses"
          description="We couldn't add the licenses right now. Please try again."
          onDismiss={() => addAllowedLicensesMutation.reset()}
        />
      )}

      {failedSpdxIds.length > 0 && (
        <LicensePolicyBanner
          variant="critical"
          title="Invalid SPDX identifiers"
          description={failedSpdxIdsDescription}
          onDismiss={dismissFailedLicensesBanner}
          failedLicenses={failedSpdxIds}
          addAllowedLicensesMutation={addAllowedLicensesMutation}
        />
      )}

      <AllowedLicensesList
        licenses={licenses}
        datePolicyAdded={datePolicyAdded}
        deleteAllowedLicensesMutation={deleteAllowedLicensesMutation}
        dismissFailedLicensesBanner={dismissFailedLicensesBanner}
      />
    </section>
  )
}
