import {SelectItem} from '@github-ui/simple-select'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {ActionList, Label} from '@primer/react'
import {clsx} from 'clsx'
import React, {useEffect, useMemo, useRef, useState} from 'react'

import type {GroupMetaData, Items as SimpleSelectItem} from '../types'
import styles from './BulkSelectorBody.module.css'
import {BulkSelectorGroup} from './BulkSelectorGroup'
import {BulkSelectorGroupSelection} from './BulkSelectorGroupSelection'

export type Items = SimpleSelectItem & {visible: boolean}

interface SelectBodyProps {
  items: Items[]
  onItemSelect?: (selectedItem: Items, items?: Items[]) => void
  onSelectionChange: (selectedItems: Items[], groupMetadata?: GroupMetaData[]) => void
  groupMetadata: GroupMetaData[]
  filterActive?: boolean
}

export const BulkSelectorBody = ({
  ref,
  items,
  onItemSelect,
  onSelectionChange,
  groupMetadata,
  filterActive,
}: SelectBodyProps & {ref?: React.Ref<HTMLLIElement>}) => {
  const [selectedItems, setSelectedItems] = useState<Items[]>(() => items.filter(item => item.selected))
  const [expandedGroups, setExpandedGroups] = useState<Set<number | string>>(
    () => new Set(groupMetadata?.filter(group => group.expanded).map(group => group.id) ?? []),
  )

  const prevItemsRef = useRef(items)
  useEffect(() => {
    if (items !== prevItemsRef.current) {
      prevItemsRef.current = items
      setSelectedItems(items.filter(item => item.selected))
    }
  }, [items])

  const prevGroupMetadataRef = useRef(groupMetadata)
  useEffect(() => {
    if (groupMetadata !== prevGroupMetadataRef.current) {
      prevGroupMetadataRef.current = groupMetadata
      setExpandedGroups(new Set(groupMetadata.filter(group => group.expanded).map(group => group.id) ?? []))
    }
  }, [groupMetadata])

  const effectiveExpandedGroups = useMemo(() => {
    if (!filterActive) return expandedGroups
    const visibleGroupIds = new Set<number | string>()
    for (const item of items) {
      if (item.visible) visibleGroupIds.add(item.groupId)
    }
    return visibleGroupIds
  }, [filterActive, expandedGroups, items])

  const getUpdatedGroupMetadata = () => {
    return groupMetadata?.map(group => ({
      ...group,
      expanded: expandedGroups.has(group.id),
    }))
  }

  const groups = useMemo(() => {
    const metaById = new Map(groupMetadata.map(meta => [meta.id, meta]))
    const selectedByGroup = new Map<number | string, Items[]>()
    for (const item of selectedItems) {
      const list = selectedByGroup.get(item.groupId)
      if (list) {
        list.push(item)
      } else {
        selectedByGroup.set(item.groupId, [item])
      }
    }

    return items.reduce((options, item) => {
      let group = options.get(item.groupId)
      if (!group) {
        const groupMeta = metaById.get(item.groupId)
        group = {
          id: item.groupId,
          items: [],
          ...(groupMeta || {}),
          expanded: effectiveExpandedGroups.has(item.groupId),
          disabled: groupMeta?.disabled ?? false,
          selected: selectedByGroup.get(item.groupId) ?? [],
        }
        options.set(item.groupId, group)
      }
      group.items.push(item)
      return options
    }, new Map<number | string, GroupMetaData & {items: Items[]; selected: Items[]}>())
  }, [items, groupMetadata, effectiveExpandedGroups, selectedItems])

  const groupCollection = Array.from(groups.entries())

  const onSelectToggle = (selectedItem: Items) => {
    const {id} = selectedItem
    if (selectedItem.disabled) return
    if (onItemSelect) onItemSelect(selectedItem)

    const updatedItem = {...selectedItem, selected: !selectedItem.selected}

    let updatedSelectedItems: Items[]
    if (!selectedItem.selected) {
      updatedSelectedItems = [...selectedItems, updatedItem]
    } else {
      updatedSelectedItems = selectedItems.filter(item => item.id !== id)
    }

    setSelectedItems(updatedSelectedItems)
    onSelectionChange(updatedSelectedItems, getUpdatedGroupMetadata())
  }

  const onGroupExpansionToggle = (groupId: number | string) => {
    setExpandedGroups(prev => {
      const updated = new Set(prev)
      if (updated.has(groupId)) {
        updated.delete(groupId)
      } else {
        updated.add(groupId)
      }
      return updated
    })
  }

  const onGroupSelectionToggle = (groupId: number | string) => {
    const group = groups.get(groupId)
    if (!group) return
    if (group.disabled) return

    const enabledVisibleItems = group.items.filter(item => item.visible && !item.disabled)
    const allEnabledSelected = enabledVisibleItems.every(item => item.selected)

    let updatedSelectedItems: Items[] = []

    if (!allEnabledSelected) {
      const newlySelectedItems = enabledVisibleItems
        .filter(item => !group.selected.some(selectedItem => selectedItem.id === item.id))
        .map(item => ({...item, selected: true}))

      updatedSelectedItems = [...selectedItems, ...newlySelectedItems]
    } else {
      const removedIds = new Set(
        selectedItems.filter(item => item.groupId === groupId && !item.disabled && item.visible).map(item => item.id),
      )

      updatedSelectedItems = selectedItems.filter(item => !removedIds.has(item.id))
    }

    setSelectedItems(updatedSelectedItems)
    onSelectionChange(updatedSelectedItems, getUpdatedGroupMetadata())
  }

  const onGroupKeyDown = (event: React.KeyboardEvent<HTMLElement>, groupId: number | string) => {
    const target = event.target as HTMLElement
    const isFromChild = target.closest('[role="treeitem"]') !== event.currentTarget

    // Events bubbling from child treeitems: only handle ArrowLeft (focus parent)
    if (isFromChild) {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- ArrowLeft on child moves focus to parent per WAI-ARIA tree pattern
      if (event.key === 'ArrowLeft') {
        event.preventDefault()
        event.currentTarget.focus()
      }
      return
    }

    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Expand/collapse and selection; arrow navigation is handled by useRovingTabIndex.
    switch (event.key) {
      case 'ArrowRight':
        if (!effectiveExpandedGroups.has(groupId)) {
          event.preventDefault()
          onGroupExpansionToggle(groupId)
        } else {
          // Already expanded: focus first child treeitem per WAI-ARIA tree pattern
          event.preventDefault()
          const firstChild = event.currentTarget.querySelector<HTMLElement>('[role="treeitem"]')
          firstChild?.focus()
        }
        break
      case 'ArrowLeft':
        if (effectiveExpandedGroups.has(groupId)) {
          event.preventDefault()
          onGroupExpansionToggle(groupId)
        }
        break
      case 'Enter':
        event.preventDefault()
        event.stopPropagation()
        onGroupExpansionToggle(groupId)
        break
      case ' ':
      case 'Spacebar':
        event.preventDefault()
        event.stopPropagation()
        onGroupSelectionToggle(groupId)
        break
    }
  }

  return (
    <>
      {groupCollection.map(([groupId, groupData], index) => {
        const visibleItems = groupData.items.filter(item => item.visible)
        const isIndeterminate = groupData.selected.length > 0 && groupData.selected.length < groupData.items.length
        const enabledVisibleItems = groupData.items.filter(item => item.visible && !item.disabled)
        const allEnabledSelected = enabledVisibleItems.every(item => item.selected)
        const isChecked = groupData.selected.length === groupData.items.length
        return visibleItems.length > 0 ? (
          <React.Fragment key={groupId}>
            <BulkSelectorGroup
              key={groupId}
              id={`${groupId.toString()}-wrapper`}
              itemsVisible={groupData.expanded}
              onClick={e => {
                const target = e.target as HTMLElement
                // Ignore clicks from child items — only toggle group when clicking the group heading area
                if (target.closest('[role="treeitem"]') !== e.currentTarget) return
                onGroupSelectionToggle(groupId)
              }}
              onKeyDown={event => onGroupKeyDown(event, groupId)}
              aria-label={`${groupData.label || `Group ${groupId}`}${groupData.tag ? `, ${groupData.tag}` : ''}. ${groupData.selected.length} selected.`}
              aria-description={`Press Enter to ${groupData.expanded ? 'collapse' : 'expand'} or Space to ${allEnabledSelected ? 'deselect' : 'select'}.`}
              aria-disabled={groupData.disabled || undefined}
              aria-checked={isChecked ? 'true' : isIndeterminate ? 'mixed' : 'false'}
            >
              <ActionList.GroupHeading
                variant="filled"
                id={groupId.toString()}
                className={clsx(styles.GroupHeading, groupData.disabled && styles.DisabledGroupHeading)}
                aria-hidden={false}
                role={undefined}
              >
                <div className="d-flex">
                  {/* <ActionList.Selection /> */}
                  <div
                    onClick={event => {
                      event.stopPropagation()
                      onGroupExpansionToggle(groupId)
                    }}
                    className={styles.GroupIconButton}
                    aria-hidden="true"
                  >
                    {groupData.expanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                  </div>
                  <BulkSelectorGroupSelection
                    checked={groupData.selected.length === groupData.items.length}
                    indeterminate={isIndeterminate}
                  />
                  <span id={`${groupId.toString()}-title`} className={styles.GroupTitle}>
                    {groupData.label || `Group ${groupId}`}
                  </span>{' '}
                  {groupData.tag ? (
                    <Label variant="secondary" className="ml-2">
                      {groupData.tag}
                    </Label>
                  ) : null}
                  <span className={styles.GroupSelectionCount}>
                    {groupData.selected.length}/{groupData.items.length}
                  </span>
                </div>
              </ActionList.GroupHeading>
              {groupData.items
                .filter(item => item.visible)
                .map((props, itemIndex) => {
                  return (
                    <SelectItem
                      key={props.id}
                      onSelect={() => onSelectToggle(props)}
                      ref={itemIndex === 0 && index === 0 ? ref : undefined}
                      className={styles.SelectItem}
                      onKeyDown={event => {
                        // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Stop Space/Enter from bubbling to group selection handler; arrow navigation is handled by useRovingTabIndex.
                        if (event.key === ' ' || event.key === 'Spacebar' || event.key === 'Enter') {
                          event.stopPropagation()
                        }
                      }}
                      aria-level={2}
                      role="treeitem"
                      {...props}
                    />
                  )
                })}
            </BulkSelectorGroup>
          </React.Fragment>
        ) : null
      })}
    </>
  )
}

BulkSelectorBody.displayName = 'BulkSelectorBody'
