import {useState} from 'react'
import {ActionList, ActionMenu, Banner, Dialog, FormControl, Stack, TextInput} from '@primer/react'
import {PackageManagerDisplayNames} from '../../types/packages'
import type {AddPackageExceptionsMutation} from '../../types/mutations'

interface PackageExceptionsAddDialogProps {
  onClose: () => void
  addPackageExceptionsMutation?: AddPackageExceptionsMutation
}

const ecosystems = Object.entries(PackageManagerDisplayNames)

export function PackageExceptionsAddDialog({onClose, addPackageExceptionsMutation}: PackageExceptionsAddDialogProps) {
  const [selectedEcosystem, setSelectedEcosystem] = useState<string | null>(null)
  const [ecosystemError, setEcosystemError] = useState('')
  const [wildcardPattern, setWildcardPattern] = useState('')
  const [wildcardPatternError, setWildcardPatternError] = useState('')

  const onWildcardChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setWildcardPattern(event.target.value)
    if (wildcardPatternError) setWildcardPatternError('')
  }

  const onEcosystemSelect = (key: string) => {
    setSelectedEcosystem(key)
    if (ecosystemError) setEcosystemError('')
  }

  const validateAndSubmit = () => {
    if (!selectedEcosystem) {
      setEcosystemError('Please select an ecosystem')
      return
    }
    const trimmedPattern = wildcardPattern.trim()
    const nonAsteriskCount = trimmedPattern.replace(/\*/g, '').length
    if (nonAsteriskCount < 2) {
      setWildcardPatternError('Pattern must contain at least 2 non-* characters')
      return
    }
    const asteriskCount = (trimmedPattern.match(/\*/g) || []).length
    if (asteriskCount > 1) {
      setWildcardPatternError('Pattern can only contain one * character')
      return
    }

    if (addPackageExceptionsMutation) {
      addPackageExceptionsMutation.mutate({
        packages: [{name: trimmedPattern, package_manager: selectedEcosystem}],
        onClose,
      })
      return
    }

    onClose()
  }

  return (
    <Dialog
      title="Add private package"
      subtitle="Matching packages with no detected license will be allowed"
      onClose={onClose}
      footerButtons={[
        {
          buttonType: 'default',
          content: 'Cancel',
          onClick: onClose,
        },
        {
          buttonType: 'primary',
          content: 'Add',
          onClick: validateAndSubmit,
        },
      ]}
    >
      <Stack align="stretch" gap="condensed">
        <Banner title="Info" hideTitle description="Only applies to packages with no detected license" />
        <FormControl>
          <FormControl.Label>Ecosystem</FormControl.Label>
          <ActionMenu>
            <ActionMenu.Button>
              {selectedEcosystem ? PackageManagerDisplayNames[selectedEcosystem] : 'Select ecosystem'}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                {ecosystems.map(([key, label]) => (
                  <ActionList.Item
                    key={key}
                    selected={selectedEcosystem === key}
                    onSelect={() => onEcosystemSelect(key)}
                  >
                    {label}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
          {ecosystemError && <FormControl.Validation variant="error">{ecosystemError}</FormControl.Validation>}
        </FormControl>
        <FormControl className="flex-self-stretch">
          <FormControl.Label>Pattern</FormControl.Label>
          <TextInput
            block
            monospace
            value={wildcardPattern}
            onChange={onWildcardChange}
            placeholder={`example/*`}
            validationStatus={wildcardPatternError ? 'error' : undefined}
          />
          <FormControl.Caption>
            Match a package name or group of packages using up to one * character.
            <br />
            Example: <span className="text-mono fgColor-default">octo-package</span>,{' '}
            <span className="text-mono fgColor-default">octo-package/*</span>
          </FormControl.Caption>
          {wildcardPatternError && (
            <FormControl.Validation variant="error">{wildcardPatternError}</FormControl.Validation>
          )}
        </FormControl>
      </Stack>
    </Dialog>
  )
}
