import type {PolicyLevel} from './policy-levels'

export interface PolicyLicense {
  allowed: LicenseEntry[]
}

export interface LicenseEntry {
  // TODO: also want to know how the license was added (in policy, exception, etc)
  spdx_id: string
  added_at: string
  level: PolicyLevel
}

export const ItemType = {
  License: 'license',
  Package: 'package exception',
} as const

export type ItemType = (typeof ItemType)[keyof typeof ItemType]

export interface AddLicensesToEnterprisePolicyPayload {
  enterprise_slug: string
  spdx_ids: string[]
  context: string
}

export interface DeleteLicensesFromEnterprisePolicyPayload {
  enterprise_slug: string
  spdx_ids: string[]
  context?: string
}

export interface DeleteLicensesFromRepositoryPolicyPayload {
  repository_slug: string
  organization_slug: string
  spdx_ids: string[]
}

export interface ValidateEnterpriseLicensesPayload {
  enterprise_slug: string
  spdx_ids: string[]
}
