import {clsx} from 'clsx'
import type {HTMLProps} from 'react'

import styles from './BulkSelectorGroup.module.css'

export const BulkSelectorGroupSelection = ({
  checked,
  indeterminate,
  className,
  ...props
}: HTMLProps<HTMLDivElement> & {checked?: boolean; indeterminate?: boolean}) => {
  return (
    <span className={styles.SelectionWrapper}>
      <div
        {...props}
        className={clsx(styles.Selection, checked && styles.Checked, indeterminate && styles.Indeterminate, className)}
        aria-hidden="true"
      />
    </span>
  )
}
BulkSelectorGroupSelection.displayName = 'BulkSelectorGroupSelection'
