import {useMemo} from 'react'
import {BulkSelector} from '@github-ui/bulk-selector'
import type {BulkSelectorProps} from '@github-ui/bulk-selector'
import pluralize from 'pluralize'
import {categoryDescriptions, licensesById} from '../../license-categories'
import type {AddAllowedLicensesMutation} from '../../types/mutations'

type Item = BulkSelectorProps['items'][number]
type GroupMetaData = BulkSelectorProps['groupMetadata'][number]

interface LicensePolicyPickerProps {
  open: boolean
  addAllowedLicensesMutation: AddAllowedLicensesMutation
  allowedSpdxIds: Set<string>
  onClose: () => void
}

const groupMetadata: GroupMetaData[] = Object.entries(categoryDescriptions).map(([id, description]) => ({
  id,
  label: id,
  tag: description,
}))

export function LicensePolicyPicker({
  open,
  addAllowedLicensesMutation,
  allowedSpdxIds,
  onClose,
}: LicensePolicyPickerProps) {
  const availableItems: Item[] = useMemo(
    () =>
      Object.entries(licensesById)
        .filter(([spdxId]) => !allowedSpdxIds.has(spdxId))
        .map(([spdxId, {name, category}]) => ({
          id: spdxId,
          label: spdxId,
          description: name,
          descriptionVariant: 'block' as const,
          groupId: category,
          selected: false,
        }))
        .sort((a, b) => a.id.localeCompare(b.id, 'en', {sensitivity: 'base'})),
    [allowedSpdxIds],
  )

  const handleClose = (savedItems: Item[]) => {
    const toAdd = savedItems.filter(item => item.selected).map(item => String(item.id))

    if (toAdd.length > 0) {
      addAllowedLicensesMutation.mutate({spdxIds: toAdd, context: 'distributed'})
    }

    onClose()
  }

  return (
    <BulkSelector
      open={open}
      onOpen={() => {}}
      renderAnchor={() => null}
      label="Select from list"
      title="Select licenses to allow"
      subtitle={count => `${count} ${pluralize('license', count)} selected`}
      placeholderText="Search licenses"
      items={availableItems}
      groupMetadata={groupMetadata}
      onClose={handleClose}
      outsideClick="cancel"
      onEscape="cancel"
      footerButtons={[{action: 'save', content: 'Add'}]}
    />
  )
}
