import {useCallback, useReducer} from 'react'

import type {LicenseEntry} from '../types/licenses'
import {PolicyLevel} from '../types/policy-levels'

type DraftState = {
  upstreamKey: string
  originalLicenses: Map<string, LicenseEntry>
  allLicenses: LicenseEntry[]
  addSpdxIds: string[]
  deleteSpdxIds: string[]
  level: PolicyLevel
}

type DraftAction =
  | {type: 'init_from_upstream'; upstreamKey: string; allowed: LicenseEntry[]; level: PolicyLevel}
  | {type: 'stage_add_licenses'; spdxIds: string[]}
  | {type: 'stage_delete_licenses'; spdxIds: string[]}

function draftReducer(state: DraftState, action: DraftAction): DraftState {
  switch (action.type) {
    case 'init_from_upstream': {
      const originalLicenses = new Map(action.allowed.map(l => [l.spdx_id, l]))
      return {
        upstreamKey: action.upstreamKey,
        originalLicenses,
        allLicenses: action.allowed,
        addSpdxIds: [],
        deleteSpdxIds: [],
        level: action.level,
      }
    }
    case 'stage_add_licenses': {
      if (state.level === PolicyLevel.Repository) return state

      // Normalize and dedupe licenses being added.
      const normalized = normalizeSpdxIds(action.spdxIds)
      if (normalized.length === 0) return state

      // The set of licenses currently in the draft (including staged adds and excluding staged deletes)
      const existingLicenses = new Set(state.allLicenses.map(l => l.spdx_id))

      // Only consider licenses that aren't already in the draft.
      const toAdd = normalized.filter(id => !existingLicenses.has(id))
      if (toAdd.length === 0) return state

      // Only consider staging an add for licenses that aren't in the original policy.
      const stagedAdds = toAdd.filter(id => !state.originalLicenses.has(id))

      return {
        ...state,
        // add licenses not already in the draft, restoring original entries when available
        allLicenses: [
          ...state.allLicenses,
          ...toAdd.map(id => state.originalLicenses.get(id) ?? createStagedLicenseEntry(id, state.level)),
        ],
        // only stage add for licenses not in the original policy
        addSpdxIds: uniqStrings([...state.addSpdxIds, ...stagedAdds]),
        // if a license was staged for delete, un-stage that delete since we're adding it back in this draft session
        deleteSpdxIds: state.deleteSpdxIds.filter(id => !toAdd.includes(id)),
      }
    }
    case 'stage_delete_licenses': {
      // Normalize and dedupe licenses being deleted.
      const normalized = normalizeSpdxIds(action.spdxIds)
      if (normalized.length === 0) return state

      // The set of licenses currently in the draft (including staged adds and excluding staged deletes)
      const existingLicenses = new Set(state.allLicenses.map(l => l.spdx_id))

      // In repository mode, only repository-level licenses can be deleted.
      const deletableLicenses =
        state.level === PolicyLevel.Repository
          ? new Set(state.allLicenses.filter(l => l.level === PolicyLevel.Repository).map(l => l.spdx_id))
          : existingLicenses

      // Only consider licenses that are in the draft.
      const toDelete = normalized.filter(id => deletableLicenses.has(id))
      if (toDelete.length === 0) return state

      // Only consider staging a delete for licenses that are in the original policy.
      const stagedDeletes = toDelete.filter(id => state.originalLicenses.has(id))

      return {
        ...state,
        // delete licenses from the draft
        allLicenses: state.allLicenses.filter(l => !toDelete.includes(l.spdx_id)),
        // only stage delete for licenses in the original policy
        deleteSpdxIds: uniqStrings([...state.deleteSpdxIds, ...stagedDeletes]),
        // if a license was staged for add, un-stage that add since we're deleting it in this draft session
        addSpdxIds: state.addSpdxIds.filter(id => !toDelete.includes(id)),
      }
    }
  }
}

/**
 * Keeps a local, mutable copy of a policy's allowed licenses.
 *
 * The `allLicenses` state is initialized from the route payload on mount and
 * re-initialized if the upstream payload meaningfully changes (e.g. after a
 * successful mutation invalidates + refetches the route query).
 */
type PolicyLicensesDraftStateBase = {
  allLicenses: LicenseEntry[]
  deleteSpdxIds: string[]
  stageDeleteLicenses: (spdxIds: string[]) => void
  resetLicensesFromUpstream: () => void
}

type PolicyLicensesDraftStateWithAdd = PolicyLicensesDraftStateBase & {
  addSpdxIds: string[]
  stageAddLicenses: (spdxIds: string[]) => void
}

export function usePolicyLicensesDraftState(
  level: typeof PolicyLevel.Repository,
  initialAllowedLicenses: LicenseEntry[],
): PolicyLicensesDraftStateBase
export function usePolicyLicensesDraftState(
  level: Exclude<PolicyLevel, typeof PolicyLevel.Repository>,
  initialAllowedLicenses: LicenseEntry[],
): PolicyLicensesDraftStateWithAdd
export function usePolicyLicensesDraftState(
  level: PolicyLevel,
  initialAllowedLicenses: LicenseEntry[],
): PolicyLicensesDraftStateBase | PolicyLicensesDraftStateWithAdd {
  const upstreamKey = policyLicensesUpstreamKey(level, initialAllowedLicenses)

  const [state, dispatch] = useReducer(draftReducer, initialAllowedLicenses, allowed => ({
    upstreamKey: policyLicensesUpstreamKey(level, allowed),
    originalLicenses: new Map(allowed.map(l => [l.spdx_id, l])),
    allLicenses: allowed,
    addSpdxIds: [],
    deleteSpdxIds: [],
    level,
  }))

  // If the server payload changes (not just a new array reference), reset local state.
  if (state.upstreamKey !== upstreamKey) {
    dispatch({type: 'init_from_upstream', upstreamKey, allowed: initialAllowedLicenses, level})
  }

  const stageAddLicenses = useCallback((spdxIds: string[]) => {
    dispatch({type: 'stage_add_licenses', spdxIds})
  }, [])

  const stageDeleteLicenses = useCallback((spdxIds: string[]) => {
    dispatch({type: 'stage_delete_licenses', spdxIds})
  }, [])

  const resetLicensesFromUpstream = useCallback(() => {
    dispatch({type: 'init_from_upstream', upstreamKey, allowed: initialAllowedLicenses, level})
  }, [initialAllowedLicenses, level, upstreamKey])

  const base: PolicyLicensesDraftStateBase = {
    allLicenses: state.allLicenses,
    deleteSpdxIds: state.deleteSpdxIds,
    stageDeleteLicenses,
    resetLicensesFromUpstream,
  }

  if (level === PolicyLevel.Repository) return base

  return {
    ...base,
    addSpdxIds: state.addSpdxIds,
    stageAddLicenses,
  }
}

function licensesKey(licenses: LicenseEntry[]) {
  return licenses.map(l => l.spdx_id).join('\u0000')
}

function policyLicensesUpstreamKey(level: PolicyLevel, licenses: LicenseEntry[]) {
  return `${level}\u0000${licensesKey(licenses)}`
}

function uniqStrings(values: string[]) {
  return Array.from(new Set(values))
}

function normalizeSpdxIds(values: string[]) {
  return uniqStrings(values.map(id => id.trim()).filter(Boolean))
}

function createStagedLicenseEntry(spdxId: string, level: PolicyLevel): LicenseEntry {
  return {
    spdx_id: spdxId,
    added_at: 'pending',
    level,
  }
}
