import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

import {PolicyLevel, IS_IN_PREVIEW} from '../types/policy-levels'
import {PolicyLevelProvider} from '../context/PolicyLevelContext'
import {PolicyEditMode, PolicyEditModeProvider} from '../context/PolicyEditModeContext'
import {UserPermissionsProvider} from '../context/UserPermissionsContext'
import {enterpriseLicensePolicyRoute} from './license-policy-route'
import {EnterpriseLicensePolicyOverview} from '../components/LicensePolicy/EnterpriseLicensePolicyOverview'

export function EnterpriseLicensePolicy() {
  // Get license policy payload from the route
  const payload = useRouteQuery(enterpriseLicensePolicyRoute, 'mainQuery')
  const canReadEnterpriseRoles = !!payload.data.can_read_enterprise_roles
  const canViewCodePolicies = !!payload.data.can_view_code_policies

  return (
    <PolicyLevelProvider policyLevel={PolicyLevel.Enterprise}>
      <PolicyEditModeProvider mode={PolicyEditMode.Draft}>
        <UserPermissionsProvider
          canReadEnterpriseRoles={canReadEnterpriseRoles}
          canViewCodePolicies={canViewCodePolicies}
        >
          <EnterpriseLicensePolicyOverview isPreview={IS_IN_PREVIEW} data={payload.data} />
        </UserPermissionsProvider>
      </PolicyEditModeProvider>
    </PolicyLevelProvider>
  )
}
