import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {
  DeleteExceptionsFromEnterprisePolicyPayload,
  DeleteExceptionsFromRepositoryPolicyPayload,
} from '../types/packages'
import {enterpriseLicensePolicyRoute, repositoryLicensePolicyRoute} from '../routes/license-policy-route'

export async function deleteExceptionsFromEnterprisePolicy(payload: DeleteExceptionsFromEnterprisePolicyPayload) {
  const deleteFromPackageExceptionsRoute = getEnterprisePackageExceptionsRoute(payload.enterprise_slug)

  const response = await reactFetchJSON(deleteFromPackageExceptionsRoute, {
    method: 'DELETE',
    body: {packages: payload.packages},
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.error || response.statusText)
  }

  const data = await response.json()
  return data
}

export async function deleteExceptionsFromRepositoryPolicy(payload: DeleteExceptionsFromRepositoryPolicyPayload) {
  const deleteFromPackageExceptionsRoute = getRepositoryPackageExceptionsRoute(
    payload.organization_slug,
    payload.repository_slug,
  )

  const response = await reactFetchJSON(deleteFromPackageExceptionsRoute, {
    method: 'DELETE',
    body: {packages: payload.packages},
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.error || response.statusText)
  }

  const data = await response.json()
  return data
}

function getEnterprisePackageExceptionsRoute(enterprise_slug: string) {
  const baseRoute = enterpriseLicensePolicyRoute.generatePath({business: enterprise_slug})
  return `${baseRoute}/exceptions`
}

function getRepositoryPackageExceptionsRoute(organization_slug: string, repository_slug: string) {
  const baseRoute = repositoryLicensePolicyRoute.generatePath({
    organization: organization_slug,
    repository: repository_slug,
  })
  return `${baseRoute}/exceptions`
}
