import {LawIcon, PlayIcon} from '@primer/octicons-react'
import {PageLayout, Stack} from '@primer/react'

import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {useUserPermissions} from '../../context/UserPermissionsContext'
import {toGenericLicensePolicyResponse} from '../../types/policies'
import type {EnterpriseLicensePolicyResponse} from '../../types/policies'
import {PolicyLevel} from '../../types/policy-levels'
import {enterpriseLicensePolicyRoute, enterpriseSingleLicensePolicyRoute} from '../../routes/license-policy-route'

import {LicensePolicyOverviewSection} from '../LicensePolicyOverviewPage/LicensePolicyOverviewSection'
import {LicensePolicyOverviewHeader} from '../LicensePolicyOverviewPage/LicensePolicyOverviewHeader'

type EnterpriseLicensePolicyOverviewProps = {
  isPreview?: boolean
  data: EnterpriseLicensePolicyResponse
}

export const ACCESS_MANAGEMENT_ITEM_TITLE = 'Enterprise license manager'
export const GOVERNANCE_ITEM_TITLE = 'Code rulesets'

export function EnterpriseLicensePolicyOverview({isPreview, data}: EnterpriseLicensePolicyOverviewProps) {
  const {allowed, packages} = toGenericLicensePolicyResponse(PolicyLevel.Enterprise, data)
  const {canReadEnterpriseRoles, canViewCodePolicies} = useUserPermissions()
  const {business} = useRouteParams(enterpriseLicensePolicyRoute)
  const encodedBusiness = encodeURIComponent(business)
  const defaultPolicyHref = enterpriseSingleLicensePolicyRoute.generatePath({business})

  return (
    <PageLayout padding="none">
      <PageLayout.Header>
        <LicensePolicyOverviewHeader isPreview={isPreview} />
      </PageLayout.Header>

      <PageLayout.Content as="div">
        <Stack gap="spacious">
          <LicensePolicyOverviewSection
            heading="Policy"
            subtitle="Define which licenses and packages can be used in your enterprise without review."
            hasAccess
            items={[
              {
                title: 'Default policy',
                description: `${allowed.length} licenses · ${packages.length} packages`,
                href: defaultPolicyHref,
              },
            ]}
          />

          <LicensePolicyOverviewSection
            heading="Access management"
            subtitle="Assign who can manage the license policy for your enterprise."
            hasAccess={canReadEnterpriseRoles}
            items={[
              {
                title: ACCESS_MANAGEMENT_ITEM_TITLE,
                description:
                  'Grants access to all organizations. Grants the ability to manage license compliance policies and requests for an enterprise and all its organizations',
                href: `/enterprises/${encodedBusiness}/enterprise_role_assignments`,
                value: 'Assign role',
                icon: <LawIcon />,
              },
            ]}
          />

          <LicensePolicyOverviewSection
            heading="Governance"
            subtitle="Branch rulesets are used to enable and enforce license compliance results before pull requests can be merged."
            hasAccess={canViewCodePolicies}
            items={[
              {
                title: GOVERNANCE_ITEM_TITLE,
                description: 'Use branch rulesets to scan and block pull requests from merging non-compliance licenses',
                href: `/enterprises/${encodedBusiness}/settings/policies/code`,
                icon: <PlayIcon />,
              },
            ]}
          />
        </Stack>
      </PageLayout.Content>
    </PageLayout>
  )
}
